'use strict';

// ─── Dependencies ────────────────────────────────────────────────────────────
const express    = require('express');
const helmet     = require('helmet');
const rateLimit  = require('express-rate-limit');
const cors       = require('cors');
const morgan     = require('morgan');

// ─── App Initialisation ───────────────────────────────────────────────────────
const app  = express();
const PORT = process.env.PORT || 3000;

// ─── Security Middleware ──────────────────────────────────────────────────────

// Sets a broad suite of protective HTTP headers (XSS, clickjacking, MIME sniffing, etc.)
app.use(helmet());

// Restrict which origins may call the API
app.use(cors({
  origin:  process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  methods: ['GET'],
}));

// Throttle repeated requests from the same IP to deter brute-force / DoS
const limiter = rateLimit({
  windowMs:       15 * 60 * 1000, // 15-minute window
  max:            100,             // max requests per window per IP
  standardHeaders: true,           // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders:   false,          // Disable `X-RateLimit-*` headers
  message:        { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ─── General Middleware ───────────────────────────────────────────────────────

// HTTP request logging  ('combined' = Apache-style, suitable for production)
app.use(morgan('combined'));

// Parse JSON bodies; hard cap at 10 kb to prevent large-body DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false }));

// ─── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // TODO: replace with a real database query; never return sensitive fields
  // (e.g. passwords / tokens) — only expose what the client genuinely needs.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];
  res.json(users);
});

// ─── Error Handling ───────────────────────────────────────────────────────────

// 404 – no route matched
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler – must declare all four parameters so Express treats it
// as an error-handling middleware rather than a regular route handler.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Never leak internal error details (stack traces, DB messages, etc.) in production
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(err.status || 500).json({ error: message });
});

// ─── Server ───────────────────────────────────────────────────────────────────

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

